<?php $isAr=$locale==='ar'; $copy=$isAr?['eyebrow'=>'أصوات سراديب','title'=>'كتّاب سراديب','intro'=>'خلف كل حكاية روح تكتب، وخلف كل كلمة عالم ينتظر أن يُكتشف.','heading'=>'اكتشف كتّابنا','search'=>'ابحث باسم الكاتب أو اهتمامه…','submit'=>'بحث','clear'=>'مسح البحث','writer'=>'كاتب في سراديب','articles'=>'مقال منشور','open'=>'اكتشف الكاتب','empty'=>'لم نعثر على كتّاب يطابقون بحثك.']:['eyebrow'=>'Saradeeeb voices','title'=>'Saradeeeb writers','intro'=>'Behind every story is a voice, and behind every word a world waiting to be discovered.','heading'=>'Discover our writers','search'=>'Search by name or interest…','submit'=>'Search','clear'=>'Clear search','writer'=>'Saradeeeb writer','articles'=>'published articles','open'=>'Discover writer','empty'=>'No writers matched your search.']; ?>
<section class="writers-directory-hero"><div class="container"><span class="writers-directory-eyebrow"><?=e($copy['eyebrow'])?></span><h1><?=e($copy['title'])?></h1><p><?=e($copy['intro'])?></p><span class="writers-directory-rule" aria-hidden="true"></span></div></section>
<section class="section writers-directory-section"><div class="container"><div class="writers-directory-heading"><div><h2><?=e($copy['heading'])?></h2><p><?=number_format($total)?> <?=e($isAr?'كاتباً':'writers')?></p></div><form class="writers-directory-search" method="get" action="<?=e(locale_url($locale,'writers'))?>"><label class="sr-only" for="writersQuery"><?=e($copy['search'])?></label><input id="writersQuery" type="search" name="q" value="<?=e($q)?>" placeholder="<?=e($copy['search'])?>"><button type="submit" class="btn btn-primary"><?=e($copy['submit'])?></button><?php if($q!==''):?><a class="btn btn-ghost" href="<?=e(locale_url($locale,'writers'))?>"><?=e($copy['clear'])?></a><?php endif;?></form></div><?php if(!$rows):?><div class="writers-directory-empty" role="status"><?=e($copy['empty'])?></div><?php else:?><div class="writers-directory-grid"><?php foreach($rows as $writer):?><article class="writers-directory-card"><a class="writers-directory-card-link" href="<?=e(writer_url((string)$writer['username'],$locale))?>"><div class="writers-directory-cover"><span aria-hidden="true">✦</span></div><div class="writers-directory-avatar"><?php if(!empty($writer['avatar'])):?><img src="<?=e($writer['avatar'])?>" alt="<?=e($writer['name'])?>" width="112" height="112" loading="lazy"><?php else:?><span><?=e(mb_substr((string)$writer['name'],0,1,'UTF-8'))?></span><?php endif;?></div><div class="writers-directory-card-body"><span class="writers-directory-badge">✓ <?=e($copy['writer'])?></span><h3><?=e((string)$writer['name'])?> <?=writer_badges_html($writer)?></h3><p class="writers-directory-role"><?=e((string)($writer['professional_title']?:$copy['writer']))?></p><p class="writers-directory-bio"><?=e(mb_substr(trim((string)$writer['bio']),0,180,'UTF-8'))?></p><div class="writers-directory-card-foot"><span><?=number_format((int)$writer['articles_count'])?> <?=e($copy['articles'])?></span><span class="writers-directory-open"><?=e($copy['open'])?> <span aria-hidden="true">←</span></span></div></div></a></article><?php endforeach;?></div><?php if($pages>1):?><nav class="writers-directory-pagination" aria-label="Pagination"><?php for($i=1;$i<=$pages;$i++):?><a class="<?=$i===$page?'active':''?>" href="<?=e(locale_url($locale,'writers').'?page='.$i.($q!==''?'&q='.rawurlencode($q):''))?>" aria-current="<?=$i===$page?'page':'false'?>"><?=$i?></a><?php endfor;?></nav><?php endif;?><?php endif;?></div></section>
